-- Load parse/classify output generated by ArchiveNamesStep.
-- The script supplies three temporary CSV paths as psql variables.
\set ON_ERROR_STOP on
BEGIN;

-- Replacing parsed rows invalidates the disposable downstream projections.
DROP SCHEMA IF EXISTS catalog CASCADE;

DROP TABLE IF EXISTS derived.archive_tag;
DROP TABLE IF EXISTS derived.archive_name_record;
DROP TABLE IF EXISTS derived.archive;
DROP TABLE IF EXISTS derived.archive_name;

CREATE TABLE IF NOT EXISTS ref.tag_category (
    category text PRIMARY KEY,
    description text NOT NULL,
    CHECK (btrim(category) <> ''),
    CHECK (btrim(description) <> '')
);

TRUNCATE ref.tag_category;
\copy ref.tag_category (category, description) FROM 'data/reference/tag_categories.csv' WITH (FORMAT csv, HEADER true)

CREATE TABLE derived.archive_name (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    romset text NOT NULL,
    archive_name text NOT NULL,
    extension text NOT NULL,
    parse_status text NOT NULL,
    parse_issues text[] NOT NULL,
    parser_version text NOT NULL,
    UNIQUE (romset, archive_name),
    CHECK (romset IN ('No-Intro', 'Redump', 'TOSEC', 'TOSEC-ISO')),
    CHECK (btrim(archive_name) <> ''),
    CHECK (parse_status IN ('parsed', 'review')),
    CHECK ((parse_status = 'parsed') = (cardinality(parse_issues) = 0))
);

CREATE TABLE derived.archive_name_record (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    archive_name_id bigint NOT NULL REFERENCES derived.archive_name(id) ON DELETE CASCADE,
    record_index integer NOT NULL CHECK (record_index > 0),
    title_candidate text NOT NULL,
    source_start integer NOT NULL CHECK (source_start >= 0),
    source_end integer NOT NULL CHECK (source_end >= source_start),
    parse_status text NOT NULL,
    parse_issues text[] NOT NULL,
    classification_issues text[] NOT NULL,
    classifier_version text NOT NULL,
    UNIQUE (archive_name_id, record_index),
    CHECK (btrim(title_candidate) <> ''),
    CHECK (parse_status IN ('parsed', 'review')),
    CHECK ((parse_status = 'parsed') = (cardinality(parse_issues) = 0))
);

CREATE TABLE derived.archive_tag (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    archive_name_record_id bigint NOT NULL
        REFERENCES derived.archive_name_record(id) ON DELETE CASCADE,
    tag_index integer NOT NULL CHECK (tag_index > 0),
    raw_value text NOT NULL,
    identifier text,
    value text,
    delimiter text NOT NULL CHECK (delimiter IN ('', '()', '[]')),
    source_start integer NOT NULL CHECK (source_start >= 0),
    source_end integer NOT NULL CHECK (source_end > source_start),
    category text NOT NULL REFERENCES ref.tag_category(category) ON DELETE RESTRICT,
    classification_status text NOT NULL
        CHECK (classification_status IN ('classified', 'unclassified')),
    rule text NOT NULL,
    details jsonb NOT NULL CHECK (jsonb_typeof(details) = 'object'),
    UNIQUE (archive_name_record_id, tag_index)
);

CREATE TABLE derived.archive (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    dat_id bigint NOT NULL REFERENCES derived.dat(id) ON DELETE CASCADE,
    archive_name_id bigint NOT NULL REFERENCES derived.archive_name(id) ON DELETE CASCADE,
    staged_row_count bigint NOT NULL CHECK (staged_row_count > 0),
    UNIQUE (dat_id, archive_name_id)
);

CREATE TEMP TABLE _archive_name_load (
    romset text, archive_name text, extension text, parse_status text,
    parse_issues jsonb, parser_version text
) ON COMMIT DROP;
CREATE TEMP TABLE _archive_name_record_load (
    romset text, archive_name text, record_index integer, title_candidate text,
    source_start integer, source_end integer, parse_status text,
    parse_issues jsonb, classification_issues jsonb, classifier_version text
) ON COMMIT DROP;
CREATE TEMP TABLE _archive_tag_load (
    romset text, archive_name text, record_index integer, tag_index integer,
    raw_value text, identifier text, value text, delimiter text, source_start integer,
    source_end integer, category text, classification_status text, rule text, details jsonb
) ON COMMIT DROP;

\copy _archive_name_load FROM '__ARCHIVE_NAMES_CSV__' WITH (FORMAT csv, HEADER true)
\copy _archive_name_record_load FROM '__ARCHIVE_NAME_RECORDS_CSV__' WITH (FORMAT csv, HEADER true)
\copy _archive_tag_load FROM '__ARCHIVE_TAGS_CSV__' WITH (FORMAT csv, HEADER true)

INSERT INTO derived.archive_name (
    romset, archive_name, extension, parse_status, parse_issues, parser_version
)
SELECT romset, archive_name, extension, parse_status,
    ARRAY(SELECT jsonb_array_elements_text(parse_issues)), parser_version
FROM _archive_name_load
ORDER BY romset, archive_name;

INSERT INTO derived.archive_name_record (
    archive_name_id, record_index, title_candidate, source_start, source_end,
    parse_status, parse_issues, classification_issues, classifier_version
)
SELECT n.id, l.record_index, l.title_candidate, l.source_start, l.source_end,
    l.parse_status, ARRAY(SELECT jsonb_array_elements_text(l.parse_issues)),
    ARRAY(SELECT jsonb_array_elements_text(l.classification_issues)),
    l.classifier_version
FROM _archive_name_record_load l
JOIN derived.archive_name n USING (romset, archive_name)
ORDER BY n.id, l.record_index;

INSERT INTO derived.archive_tag (
    archive_name_record_id, tag_index, raw_value, identifier, value, delimiter,
    source_start, source_end, category, classification_status, rule, details
)
SELECT r.id, l.tag_index, l.raw_value, l.identifier, l.value,
    coalesce(l.delimiter, ''), l.source_start, l.source_end, l.category,
    l.classification_status, l.rule, l.details
FROM _archive_tag_load l
JOIN derived.archive_name n USING (romset, archive_name)
JOIN derived.archive_name_record r
  ON r.archive_name_id = n.id AND r.record_index = l.record_index
ORDER BY r.id, l.tag_index;

INSERT INTO derived.archive (dat_id, archive_name_id, staged_row_count)
SELECT d.id, n.id, count(*)
FROM staging.rv_files rf
JOIN derived.dat d
  ON d.dat_path = rf.dat_root_full_name AND d.dat_name = rf.dat_name
JOIN derived.archive_name n
  ON n.romset = d.romset AND n.archive_name = rf.game_display_name
WHERE nullif(btrim(rf.game_display_name), '') IS NOT NULL
GROUP BY d.id, n.id
ORDER BY d.id, n.id;

DO $$
DECLARE
    missing_records bigint;
    missing_tags bigint;
    missing_archives bigint;
BEGIN
    SELECT count(*) INTO missing_records
    FROM _archive_name_record_load l
    LEFT JOIN derived.archive_name n USING (romset, archive_name)
    LEFT JOIN derived.archive_name_record r
      ON r.archive_name_id = n.id AND r.record_index = l.record_index
    WHERE r.id IS NULL;

    SELECT count(*) INTO missing_tags
    FROM _archive_tag_load l
    LEFT JOIN derived.archive_name n USING (romset, archive_name)
    LEFT JOIN derived.archive_name_record r
      ON r.archive_name_id = n.id AND r.record_index = l.record_index
    LEFT JOIN derived.archive_tag t
      ON t.archive_name_record_id = r.id AND t.tag_index = l.tag_index
    WHERE t.id IS NULL;

    SELECT count(*) INTO missing_archives
    FROM (
        SELECT DISTINCT d.id AS dat_id, n.id AS archive_name_id
        FROM staging.rv_files rf
        JOIN derived.dat d
          ON d.dat_path = rf.dat_root_full_name AND d.dat_name = rf.dat_name
        JOIN derived.archive_name n
          ON n.romset = d.romset AND n.archive_name = rf.game_display_name
        WHERE nullif(btrim(rf.game_display_name), '') IS NOT NULL
    ) expected
    LEFT JOIN derived.archive a USING (dat_id, archive_name_id)
    WHERE a.id IS NULL;

    IF missing_records <> 0 OR missing_tags <> 0 OR missing_archives <> 0 THEN
        RAISE EXCEPTION 'incomplete archive load: records %, tags %, archives %',
            missing_records, missing_tags, missing_archives;
    END IF;
END;
$$;

CREATE INDEX archive_name_status_idx ON derived.archive_name(parse_status);
CREATE INDEX archive_name_record_title_idx ON derived.archive_name_record(title_candidate);
CREATE INDEX archive_name_record_review_idx
    ON derived.archive_name_record(parse_status) WHERE parse_status = 'review';
CREATE INDEX archive_tag_category_idx ON derived.archive_tag(category);
CREATE INDEX archive_tag_review_idx
    ON derived.archive_tag(classification_status) WHERE classification_status = 'unclassified';
CREATE INDEX archive_name_link_idx ON derived.archive(archive_name_id);

COMMENT ON TABLE ref.tag_category IS
    'Maintained tag-classification categories loaded from data/reference/tag_categories.csv.';
COMMENT ON TABLE derived.archive_name IS
    'One rebuildable structural parse per collection and original archive name.';
COMMENT ON TABLE derived.archive_name_record IS
    'Titles encoded by an archive name; compound TOSEC names contain multiple ordered records.';
COMMENT ON TABLE derived.archive_tag IS
    'Ordered raw tags and rebuildable collection-specific interpretations.';
COMMENT ON TABLE derived.archive IS
    'Rebuildable association of a source DAT with a parsed archive name.';

ANALYZE ref.tag_category;
ANALYZE derived.archive_name;
ANALYZE derived.archive_name_record;
ANALYZE derived.archive_tag;
ANALYZE derived.archive;

COMMIT;
